void
CPlayerSaveData::initializeJobData(char *_strId,char *_strName,int _iJob)
{
	assert(g_aPlayerJobBaseInfo[_iJob/2].m_iLevel	==	1	&&	"뭥미? 직업 추가된거 정보 입력이 안 되었던가 직업 인덱스가 이상하다!!");
	assert(g_aPlayer1LvSetting[_iJob].m_wStatus		<=	2	&&	"뭥미? 직업 추가된거 정보 입력이 안 되었던가 직업 인덱스가 이상하다!!");

	reset();
	strcpy(m_strId,_strId);
	strcpy(m_strName,_strName);

	m_iHP			=	m_iMaxHP;
	m_wJob			=	_iJob;//현재 직업

	memcpy(&m_iLevel,&g_aPlayerJobBaseInfo[_iJob/2],sizeof(CJobBasicDataDefine));
	
	g_im.generateItemByBaseItem(&m_aEquip[dEQUIP_WEAPON],g_aPlayer1LvSetting[_iJob].m_aWeapon[0],g_aPlayer1LvSetting[_iJob].m_aWeaponCount[0]);
	g_im.generateItemByBaseItem(&m_aEquip[dEQUIP_WEAPON_2],g_aPlayer1LvSetting[_iJob].m_aWeapon[1],g_aPlayer1LvSetting[_iJob].m_aWeaponCount[1]);
	g_im.generateItemByBaseItem(&m_aEquip[dEQUIP_SHIELD_BULLET],g_aPlayer1LvSetting[_iJob].m_wShield,1);
	g_im.generateItemByBaseItem(&m_aEquip[dEQUIP_GLOVE],g_aPlayer1LvSetting[_iJob].m_wGlove,1);
	g_im.generateItemByBaseItem(&m_aEquip[dEQUIP_BELT],g_aPlayer1LvSetting[_iJob].m_wBelt,1);
	g_im.generateItemByBaseItem(&m_aEquip[dEQUIP_SHIELD_BULLET],g_aPlayer1LvSetting[_iJob].m_wBullet,g_aPlayer1LvSetting[_iJob].m_wBulletCount);
	g_im.generateItemByBaseItem(&m_aItems[0],g_aPlayer1LvSetting[_iJob].m_wSlot0Item,g_aPlayer1LvSetting[_iJob].m_wSlot0ItemCount);
	
	m_aEquip[dEQUIP_WEAPON].m_dwSerial			=	0;
	m_aEquip[dEQUIP_WEAPON_2].m_dwSerial		=	0;
	m_aEquip[dEQUIP_SHIELD_BULLET].m_dwSerial	=	0;
	m_aEquip[dEQUIP_GLOVE].m_dwSerial			=	0;
	m_aEquip[dEQUIP_BELT].m_dwSerial			=	0;

	m_wCurrentField								=	433;

	int	iSkillCount								=	0;
	int	iDefaultSkill							=	g_aPlayer1LvSetting[_iJob].m_wDefaultSkill;
	
	if (iDefaultSkill	!=	0xffff)
	{
		m_aAbility[iSkillCount].m_wSkill	=	iDefaultSkill;
		m_aAbility[iSkillCount].m_wLevel	=	1;
		
		iSkillCount++;
	}
	
	for(int iSkillIndex=0,iCount=0;iSkillIndex<dMAX_SKILL && iCount<g_sm.m_iSkillCount;iSkillIndex++)
	{
		CSkill	*lpSkill	=	&g_aSkill[iSkillIndex];
		
		if	(lpSkill->m_wSerial	==	0xffff)
			continue;

		iCount++;
		
		if	(lpSkill->m_wEnableJob/2	!=	m_wJob/2	)
			continue;

		if	(lpSkill->m_wSerial		==	iDefaultSkill	)
			continue;
		
		m_aAbility[iSkillCount].m_wSkill	=	iSkillIndex;
		m_aAbility[iSkillCount].m_wLevel	=	0;
		
		iSkillCount++;
	}
}

//
//	특정 레벨로 플레이어 데이터 재 설정
void
cACTOR::rebuildPlayerData(int _iLevel)
{
	cACTOR	temp;

	int		iOldJob	=	m_wJob;

	if	(m_wJob == dJOB_WEREWOLF	||	m_wJob == dJOB_FALLEN_ANGEL	||	m_wJob == dJOB_DEVIL	||	m_wJob == dJOB_MAGICAL_GIRL)
		m_wJob--;
	
	temp.initializeJobData("aaa","aaaa",m_wJob);
	
	m_iLevel				=	max(_iLevel-1,1);
	
	CPlayerSaveData	*lpJob	=	&temp;
	int				iJob	=	m_wJob/2,i;

	m_iExperience		=	g_aExpTable[m_iLevel]-1;
	m_dwSkillExperience	=	0;
	m_wLevelPoint		=	0;
	m_sStrength			=	lpJob->m_sStrength;		//	힘			5 1,000
	m_sAgility			=	lpJob->m_sAgility;		//	민첩성		5 1,000
	m_sConstitution		=	lpJob->m_sConstitution;	//	건강		5 1,000
	m_sWisdom			=	lpJob->m_sWisdom;		//	지혜		5 1,000
	m_sIntelligence		=	lpJob->m_sIntelligence;	//	지식		5 1,000
	m_sCharisma			=	lpJob->m_sCharisma;		//	카리스마	5 1,000
	m_sLuck				=	lpJob->m_sLuck;			//	운			5 1,000
	m_iCP				=	lpJob->m_iCP;
	
	for (i=2;i<=m_iLevel;i++)
	{
		//		힘	민첩성	건강	지식	지혜	카리스마	운	사용자
		m_dwSkillExperience	+=	min(i,100);
		
		m_sStrength			+=	g_aiLevelUpValue[iJob][0];
		m_sAgility			+=	g_aiLevelUpValue[iJob][1];
		m_sConstitution		+=	g_aiLevelUpValue[iJob][2];
		m_sIntelligence		+=	g_aiLevelUpValue[iJob][3];
		m_sWisdom			+=	g_aiLevelUpValue[iJob][4];
		m_sCharisma			+=	g_aiLevelUpValue[iJob][5];
		m_sLuck				+=	g_aiLevelUpValue[iJob][6];
		m_wLevelPoint		+=	g_aiLevelUpValue[iJob][7];
	}

	m_wLevelPoint		+=	m_bf4CH5StateBonusCount*5;
	m_dwSkillExperience	+=	m_bf4CH5SkillBonusCount*100;

	m_dwSkillExperience	+=	c_aBonusSkillPointForRebirth[m_bf4RebirthCount];
	m_wLevelPoint		+=	c_aBonusStatePointForRebirth[m_bf4RebirthCount];

	if	(m_bf10Costume)
	{
		m_dwSkillExperience++;

		for (int i=0;i<dABILITY_COUNT;i++)	
		{
			m_aAbility[i].m_wSkill	=	910+i;
			m_aAbility[i].m_wLevel	=	0;

			if	(g_aSkill[m_aAbility[i].m_wSkill].m_wSerial	==	0xffff)
				m_aAbility[i].m_wSkill	=	0xffff;
		}
	}
	else
		memcpy(m_aAbility,lpJob->m_aAbility,sizeof(m_aAbility));
	
	if	(_iLevel	>	1)
		increaseExperience(1);

	if	(m_wJob	!=	iOldJob)
	{
		m_wJob	=	iOldJob;

		sendTransformation(eTR_BY_SKILL);
	}
	memset(m_aActiveReaction,0xff,sizeof(m_aActiveReaction));		// 리액션스킬도 ..초기화시킨다.
	memset(m_aPassiveSkill,0xffff,sizeof(m_aPassiveSkill));		// 패시브스킬들.
	buildPower();
	sendRedistribute(eREDISTRIBUTE_SKILL);
}

void
cACTOR::resetOneState(int _iItemSlot,int _iPower)
{
	cItem	*lpItem	=	getInventoryItem(_iItemSlot);

	if	(!lpItem	||	lpItem->checkFirstEffect(eIE_CH5_REVERSE_STATE_POINT)	==	FALSE	||	_iPower	<	0	||	_iPower	>=	7)
		return;

	CPlayerSaveData	player;

	int	iJob	=	m_wJob;

	if	(iJob == dJOB_WEREWOLF	||	iJob == dJOB_FALLEN_ANGEL	||	iJob	== dJOB_DEVIL	||	iJob	== dJOB_MAGICAL_GIRL)
		iJob--;

	CPlayerSaveData		*lpJob	=	&g_aDefaultPlayerJobData[iJob];

	iJob	/=	2;

	int	iStrength		=	lpJob->m_sStrength;		//	힘			5 1,000
	int	iAgility		=	lpJob->m_sAgility;		//	민첩성		5 1,000
	int	iConstitution	=	lpJob->m_sConstitution;	//	건강		5 1,000
	int	iWisdom			=	lpJob->m_sWisdom;		//	지혜		5 1,000
	int	iIntelligence	=	lpJob->m_sIntelligence;	//	지식		5 1,000
	int	iCharisma		=	lpJob->m_sCharisma;		//	카리스마	5 1,000
	int	iLuck			=	lpJob->m_sLuck;			//	운			5 1,000

	for (int i=2;i<=m_iLevel;i++)
	{
//		힘	민첩성	건강	지식	지혜	카리스마	운	사용자
		iStrength		+=	g_aiLevelUpValue[iJob][0];
		iAgility		+=	g_aiLevelUpValue[iJob][1];
		iConstitution	+=	g_aiLevelUpValue[iJob][2];
		iIntelligence	+=	g_aiLevelUpValue[iJob][3];
		iWisdom			+=	g_aiLevelUpValue[iJob][4];
		iCharisma		+=	g_aiLevelUpValue[iJob][5];
		iLuck			+=	g_aiLevelUpValue[iJob][6];
	}

	int	iDeltaValue	=	0;
	int	iValue		=	0;

	switch(_iPower)
	{
		case	0	:	//"힘",
			iDeltaValue	=	m_sStrength-iStrength;
			m_sStrength	=	iStrength;
			iValue		=	iStrength;
			break;
		case	1	:	//"민첩성",
			iDeltaValue	=	m_sAgility-iAgility;
			m_sAgility	=	iAgility;
			iValue		=	iAgility;
			break;
		case	2	:	//"건강",
			iDeltaValue	=	m_sConstitution-iConstitution;
			m_sConstitution	=	iConstitution;
			iValue		=	iConstitution;
			break;
		case	3	:	//"카리스마",
			iDeltaValue	=	m_sCharisma-iCharisma;
			m_sCharisma	=	iCharisma;
			iValue		=	iCharisma;
			break;
		case	4	:	//"지식",
			iDeltaValue		=	m_sIntelligence-iIntelligence;
			m_sIntelligence	=	iIntelligence;
			iValue			=	iIntelligence;
			break;
		case	5	:	//"지혜",
			iDeltaValue		=	m_sWisdom-iWisdom;
			m_sWisdom		=	iWisdom;
			iValue			=	iWisdom;
			break;
		case	6	:	//"행운",
			iDeltaValue		=	m_sLuck-iLuck;
			m_sLuck			=	iLuck;
			iValue			=	iLuck;
			break;
	}

	m_wLevelPoint	+=	iDeltaValue;

	lpItem->decreaseCount(1);

	sendEtcWork(eEW_CH5_RESET_ONE_STATE,_iItemSlot,_iPower,iValue,m_wLevelPoint);

	m_bf4CH5PeneltyHPBonusCount		=	m_bf4CH5HPBonusCount;
	m_bf4CH5PeneltyCPBonusCount		=	m_bf4CH5CPBonusCount;

	sendEtcWork(eEW_CH5_REVERSE_ITEM_PENELTY);
}




BOOL
cACTOR::rebirth(BOOL _bIsCompleteBankWork, BOOL _bIsNotResetLevel)	//	전생
{
	if	(m_bf4RebirthCount	>=	dLIMIT_REBIRTH_COUNT)
		return	FALSE;
	
	if	(_bIsNotResetLevel)
	{
		m_bf4RebirthCount++;
		
		sendEtcWork(eEW_REBIRTH,_bIsNotResetLevel);
		sendPlayerInfo(this);
		sendRebirthLog(m_iLevel,m_iExperience);	
		immediatelySendSaveDataToDBMemory();
		
		addSendVerySimpleInfo();
		return	TRUE;
	}

	if	(!_bIsCompleteBankWork)
	{
		m_bf1IsProcessRebirth	=	TRUE;
		
		askOpenBank();
		
		return	TRUE;
	}

	int	i;
	
	for (i=0;i<dOWN_SUMMON_BEAST_COUNT;i++)
	{
		cACTOR	*lpBeast	=	getSummonBeastActor(i);
		
		if	(!lpBeast)
			continue;

		if	(m_wRidingDogTime)
			if	(lpBeast->m_wSummonBeastType	==	eSBT_KELBY)
				getOffFromDog();

		lpBeast->bookingDeath(NULL,TRUE);
		removeSummonBeast(i);
	}

	for (i=0;i<dOWN_ITEM_COUNT;i++)
	{
		cItem	*lpItem	=	(cItem *)&m_aItems[i];

		if	(lpItem->m_wBaseItem == 0xffff || !lpItem->isBreedingRecordBook())
			continue;

		cPetDefine	*lpPetInfo	=	(cPetDefine	*)&lpItem->m_bCount;

		lpPetInfo->m_bf10Level		=	1;
		lpItem->m_dwSerial			=	0;
	}

	for (i=0;i<m_bf6ExtraInventorySize;i++)
	{
		cItem	*lpItem	=	(cItem *)&m_aExtraInventory[i];

		if	(lpItem->m_wBaseItem == 0xffff || !lpItem->isBreedingRecordBook())
			continue;

		cPetDefine	*lpPetInfo	=	(cPetDefine	*)&lpItem->m_bCount;

		lpPetInfo->m_bf10Level		=	1;
		lpItem->m_dwSerial			=	0;
	}

	m_bf1IsProcessRebirth	=	FALSE;
	m_bf4RebirthCount++;

	sendEtcWork(eEW_REBIRTH);

	int		iPreLevel	=	m_iLevel;
	int		iPreExp		=	m_iExperience;

	m_iLevel		=	1;
	m_iExperience	=	0;

 	for (int iLevel=600;iLevel<iPreLevel;++iLevel)
 	{
 		_increaseExperience(g_aExpTable[iLevel], FALSE);
 	}
 
 	_increaseExperience(iPreExp, FALSE);

	resetSkillPoint();
	resetStatePoint();

	sendPlayerInfo(this);
	sendRebirthLog(iPreLevel,iPreExp);	


	m_bf1IsLevelDown	=	TRUE;

	immediatelySendSaveDataToDBMemory();

	addSendVerySimpleInfo();

	return	TRUE;
}

void
cACTOR::resetOneSkill(int _iItemSlot,int _iAbility)
{
	cItem	*lpItem	=	getInventoryItem(_iItemSlot);

	if	(!lpItem	||	lpItem->checkFirstEffect(eIE_CH5_REVERSE_SKILL_POINT)	==	FALSE	||	_iAbility	<	0	||	_iAbility	>=	dABILITY_COUNT)
		return;

	int			iRequireLevel	=	0;
	cAbility	*lpAbility		=	&m_aAbility[_iAbility];
	CSkill		*lpSrcSkill		=	lpAbility->getSkill();

	if	(lpSrcSkill	==	NULL)
		return;

	int	iJob	=	m_wJob;

	if	(iJob == dJOB_WEREWOLF	||	iJob == dJOB_FALLEN_ANGEL	||	iJob	== dJOB_DEVIL	||	iJob	== dJOB_MAGICAL_GIRL)
		iJob--;

	for (int i=0;i<dABILITY_COUNT;i++)
	{
		if	(m_aAbility[i].m_wLevel	==	0)
			continue;

		CSkill	*lpSkill	=	m_aAbility[i].getSkill();

		if	(!lpSkill)
			continue;

		for (int j=0;j<dMAX_REQUIRE_SKILL_COUNT;j++)
		{
			if	(lpSkill->m_aRequireSkill[j].m_wSkill	==	lpSrcSkill->m_wSerial)
				iRequireLevel	=	max(iRequireLevel,lpSkill->m_aRequireSkill[j].m_wLevel);
		}
	}

	iRequireLevel	=	max(iRequireLevel,g_aDefaultPlayerJobData[iJob].m_aAbility[_iAbility].m_wLevel);

	int	iDeltaLevel	=	lpAbility->m_wLevel-iRequireLevel;
	int	iResetPoint	=	0;

	for (;iDeltaLevel;)
	{
		lpAbility->m_wLevel--;
		iResetPoint	+=	lpAbility->getRemainExpForLevelUp();
		iDeltaLevel--;
	}

	m_dwSkillExperience	+=	iResetPoint;

	lpItem->decreaseCount(1);

	sendEtcWork(eEW_CH5_RESET_ONE_SKILL,_iItemSlot,_iAbility,lpAbility->m_wLevel,m_dwSkillExperience);

	m_bf4CH5PeneltyHPBonusCount		=	m_bf4CH5HPBonusCount;
	m_bf4CH5PeneltyCPBonusCount		=	m_bf4CH5CPBonusCount;

	sendEtcWork(eEW_CH5_REVERSE_ITEM_PENELTY);
}

