//
//	스탯 재분배
BOOL
cACTOR::resetStatePoint()
{
	cACTOR	temp;
	WORD	iOldJob		=	m_wJob;
	int		iJob		=	m_wJob;
	
	if	(m_wJob == dJOB_WEREWOLF	||	m_wJob == dJOB_FALLEN_ANGEL	||	m_wJob == dJOB_DEVIL	||	m_wJob == dJOB_MAGICAL_GIRL)
	{
		iJob--;
	}
	
	temp.initializeJobData("aaa","aaaa",iJob);
	
	CPlayerSaveData		*lpJob		=	&temp;
	int					iCharacter	=	iJob/2,i;

	int	iLevelPoint		=	m_bf4CH5StateBonusCount*5;
	iLevelPoint			+=	c_aBonusStatePointForRebirth[m_bf4RebirthCount];
	
	int	iStrength		=	lpJob->m_sStrength;		//	힘			5 1,000
	int	iAgility		=	lpJob->m_sAgility;		//	민첩성		5 1,000
	int	iConstitution	=	lpJob->m_sConstitution;	//	건강		5 1,000
	int	iIntelligence	=	lpJob->m_sIntelligence;	//	지식		5 1,000
	int	iWisdom			=	lpJob->m_sWisdom;		//	지혜		5 1,000
	int	iCharisma		=	lpJob->m_sCharisma;		//	카리스마	5 1,000
	int	iLuck			=	lpJob->m_sLuck;			//	운			5 1,000

	for (i=2;i<=m_iLevel;i++)
	{
		//		힘	민첩성	건강	지식	지혜	카리스마	운	사용자
		iStrength		+=	g_aiLevelUpValue[iCharacter][0];
		iAgility		+=	g_aiLevelUpValue[iCharacter][1];
		iConstitution	+=	g_aiLevelUpValue[iCharacter][2];
		iIntelligence	+=	g_aiLevelUpValue[iCharacter][3];
		iWisdom			+=	g_aiLevelUpValue[iCharacter][4];
		iCharisma		+=	g_aiLevelUpValue[iCharacter][5];
		iLuck			+=	g_aiLevelUpValue[iCharacter][6];
		iLevelPoint		+=	g_aiLevelUpValue[iCharacter][7];
	}

	if	(m_wLevelPoint	==	iLevelPoint		&&	m_sLuck		==	iLuck		&&
		m_sStrength		==	iStrength		&&	iAgility	==	m_sAgility	&&	iConstitution	==	m_sConstitution	&&
		iIntelligence	==	m_sIntelligence	&&	iWisdom		==	m_sWisdom	&&	iCharisma		==	m_sCharisma		)
		return	FALSE;

	m_wLevelPoint	=	iLevelPoint;
	m_sLuck			=	iLuck;
	m_sStrength		=	iStrength;
	m_sAgility		=	iAgility;
	m_sConstitution	=	iConstitution;
	m_sIntelligence	=	iIntelligence;
	m_sWisdom		=	iWisdom;
	m_sCharisma		=	iCharisma;

	m_iCP			=	lpJob->m_iCP;
	
	if	(iJob	!=	m_wJob)
	{
		sendTransformation();
		m_wJob	=	iJob;

	}
	buildPower();
	return	TRUE;
}

//
//	스탯 재분배
BOOL
cACTOR::resetOneStatePoint(int _iState)
{
	cACTOR	temp;
	int		iJob		=	m_wJob;
	
	if	(m_wJob == dJOB_WEREWOLF	||	m_wJob == dJOB_FALLEN_ANGEL	||	m_wJob == dJOB_DEVIL	||	m_wJob == dJOB_MAGICAL_GIRL)
		iJob--;
	
	temp.initializeJobData("aaa","aaaa",iJob);

	CPlayerSaveData	*lpJob		=	&temp;
	int				iCharacter	=	iJob/2,i;
	short*			lpsState	=	NULL;
	int				iJobBasicState=	0;

	switch(_iState)
	{
		case	eSTATE_STRENGTH		:
			lpsState	=	&m_sStrength;
			iJobBasicState=	lpJob->m_sStrength;
			break;
		case	eSTATE_AGILITY		:
			lpsState	=	&m_sAgility;
			iJobBasicState=	lpJob->m_sAgility;
			break;
		case	eSTATE_CONSTITUTION	:
			lpsState	=	&m_sConstitution;
			iJobBasicState=	lpJob->m_sConstitution;
			break;
		case	eSTATE_INTELLIGENCE	:
			lpsState	=	&m_sIntelligence;
			iJobBasicState=	lpJob->m_sIntelligence;
			break;
		case	eSTATE_WISDOM	:
			lpsState	=	&m_sWisdom;
			iJobBasicState=	lpJob->m_sWisdom;
			break;
		case	eSTATE_CHARISMA	:
			lpsState	=	&m_sCharisma;
			iJobBasicState=	lpJob->m_sCharisma;
			break;
		case	eSTATE_LUCK		:
			lpsState	=	&m_sLuck;
			iJobBasicState=	lpJob->m_sLuck;
			break;
	}

	int		iOrgState	=	(*lpsState);
	(*lpsState)			=	iJobBasicState;

	for (i=2;i<=m_iLevel;i++)
		(*lpsState)		+=	g_aiLevelUpValue[iCharacter][_iState];

	int	iResetPoint		=	iOrgState-(*lpsState);

	if	(iResetPoint	==	0)
		return	FALSE;
	
	m_wLevelPoint		+=	iResetPoint;
	if	(iJob	!=	m_wJob)
	{
		sendTransformation();
		m_wJob	=	iJob;

	}		
	buildPower();

	return	TRUE;
}

//
//	스탯 재분배
BOOL
cACTOR::resetSkillPoint()
{
	cACTOR		temp;
	WORD		wOldJob		=	m_wJob;
	cAbility	aAbility[dABILITY_COUNT];
	
	if	(m_wJob == dJOB_WEREWOLF	||	m_wJob == dJOB_FALLEN_ANGEL	||	m_wJob == dJOB_DEVIL	||	m_wJob == dJOB_MAGICAL_GIRL)
		m_wJob--;

	temp.initializeJobData("aaa","aaaa",m_wJob);
	
	DWORD	dwSkillExperience	=	getSkillPointSumByLevel();

	if	(m_bf10Costume)
	{
		m_dwSkillExperience++;

		for (int i=0;i<dABILITY_COUNT;i++)	
		{
			aAbility[i].m_wSkill	=	910+i;
			aAbility[i].m_wLevel	=	0;

			if	(g_aSkill[aAbility[i].m_wSkill].m_wSerial	==	0xffff)
				aAbility[i].m_wSkill	=	0xffff;
		}
	}
	else
		memcpy(aAbility,temp.m_aAbility,sizeof(m_aAbility));

	if	(dwSkillExperience	==	m_dwSkillExperience)
	{
		BOOL	bIsChanged	=	FALSE;

		for (int i=0;i<dABILITY_COUNT;i++)	
		{
			if	(aAbility[i].m_wSkill	!=	m_aAbility[i].m_wSkill	||	aAbility[i].m_wLevel	!=	m_aAbility[i].m_wLevel)
			{
				bIsChanged	=	TRUE;

				break;
			}
		}

		if	(bIsChanged	==	FALSE)
			return	FALSE;
	}

	memcpy(m_aAbility,aAbility,sizeof(m_aAbility));

	m_dwSkillExperience	=	dwSkillExperience;

	if	(m_wJob	!=	wOldJob)
	{
		m_wJob	=	wOldJob;

		sendTransformation(eTR_BY_SKILL);
	}

	memset(m_aActiveReaction,0xff,sizeof(m_aActiveReaction));
	memset(m_aPassiveSkill,0xffff,sizeof(m_aPassiveSkill));		// 패시브스킬들.

	return	TRUE;
}

