BOOL
cACTOR::openTreasureBox()
{
	if	(m_wTreasureBoxXPos	==	0xffff)
	{
		SG_ARCA_WORK	packet;

		packet.base.set(sizeof(packet),dSG_ARCA_WORK);
		packet.wArcaIndex	=	0x7fff;
		packet.wWork		=	eAW_REMOVE;

		g_userPM.add(m_iClientSerial,&packet,packet.base.wSize);

		return	FALSE;
	}

	cRECT	rect;

	rect.Set(m_wTreasureBoxXPos-64,m_wTreasureBoxYPos-64,m_wTreasureBoxXPos+64,m_wTreasureBoxYPos+32);

	if	(!rect.Isin(m_pos.x,m_pos.y))
	{
		sendArcaWork(0x7fff,eAW_IS_FAILED);

		return	FALSE;
	}

	m_wTreasureBoxXPos		=	0xffff;
	m_wTreasureBoxYPos		=	0xffff;

	sendEtcWork(eEW_OPEN_TREASURE_BOX);

	BOOL	bIsActiveTime	=	FALSE;

	m_wRedStonePoint++;

	if	(random(100000)	<	5)	//	0.0005%
	{
		if	(g_iBoostExpByTreasureMapEventCount	<	dMAX_BOOST_EXP_COUNT_FOR_TREASURE_MAP_EVENT)
		{
			sendTresureMapLog(eTME_LOG_BOOST_EXP_IN_SERVER);
			g_game.sendWPBoostPowerByEvent(eBPBE_TM_EXP,m_strName);
			return	TRUE;
		}

		bIsActiveTime	=	TRUE;
	}

	if	(bIsActiveTime	||	random(10000)	<	2)	//	0.002%
	{
		if	(g_iBoostGoldByTreasureMapEventCount<	dMAX_BOOST_GOLD_COUNT_FOR_TREASURE_MAP_EVENT)
		{
			sendTresureMapLog(eTME_LOG_BOOST_GOLD_IN_SERVER);
			g_game.sendWPBoostPowerByEvent(eBPBE_TM_GOLD,m_strName);
			return	TRUE;
		}

		bIsActiveTime	=	TRUE;
	}

	int	iChance	=	30-max((m_iLevel-100)/2,0)/2;	//	100레벨 이하에서는 경험치 2배 확률이 30%

	iChance		=	max(iChance,2);

	if	(bIsActiveTime	||	random(100)	<	iChance)
	{
		m_wBoostExpSecondByTreasureMapEvent	+=	dBOOST_PLAYER_EXP_SECOND_BY_TREASURE_MAP;

		sendTresureMapLog(eTME_LOG_BOOST_PLAYER_EXP);

		sendEtcWork(eEW_BOOST_EXP_SECOND_BY_TREASURE_MAP_EVENT,dBOOST_PLAYER_EXP_SECOND_BY_TREASURE_MAP,g_iBoostExpSecondByTreasureMapEventInServer);

		return	TRUE;
	}

	if	(random(100)	<	25)
	{
		m_wBoostGoldSecondByTreasureMapEvent+=	dBOOST_PLAYER_GOLD_SECOND_BY_TREASURE_MAP;

		sendTresureMapLog(eTME_LOG_BOOST_PLAYER_GOLD);

		sendEtcWork(eEW_BOOST_GOLD_SECOND_BY_TREASURE_MAP_EVENT,dBOOST_PLAYER_EXP_SECOND_BY_TREASURE_MAP,g_iBoostGoldSecondByTreasureMapEventInServer);

		bIsActiveTime	=	TRUE;
	}

	if	(bIsActiveTime	||	random(100)	<	50)
	{
		int	iGetGold	=	m_iLevel	*	500;

		DWORD	dwGold	=	m_iGold;
		dwGold			+=	iGetGold;

		if	(dwGold		<=	dMAX_OWN_GOLD)
		{
			cItem	item;

			item.reset();
			item.m_wBaseItem	=	dITEM_MONEY;
			item.m_dwSerial		=	iGetGold;

			sendPickItemLog(&item,ePIM_TREASURE_MAP_EVENT);

			m_iGold				+=	iGetGold;

			updateGoldLog(iGetGold,eGET_GOLD_BY_TREASURE_BOX);

			sendAddGold(iGetGold);

			sendEtcWork(eEW_FOUND_GOLD_IN_TREASURE_BOX);

			return	TRUE;
		}

		if	(bIsActiveTime)
			return	TRUE;
	}

	sendEtcWork(eEW_FAILED_TO_USE_TREASURE_MAP);

	return	FALSE;
}

void
cACTOR::selectAllignment(int _iItem,int _iValue)
{
	cItem	*lpItem	=	getInventoryItem(_iItem);

	if	(!lpItem || lpItem->checkFirstEffect(eIE_CH5_SELECT_ALLIGNMENT)	==	FALSE)
		return;

	int					iTitleLevel	=	0;
	CPlayerTitleInfo	*lpTitle	=	getTitle(eTN_RED_STONE_HUNTER);

	if	(!lpTitle)
		return;

	iTitleLevel	=	lpTitle->m_bLevel;

	int	iRange	=	15+iTitleLevel;

	if	(_iValue	<	-iRange || _iValue > iRange)
		return;

	m_sAllignment	=	_iValue;

	lpItem->decreaseCount(1);

	sendEtcWork(eEW_SET_ALLIGNMENT,_iItem,_iValue);
}

void
cACTOR::readyToDuel(int _iDuelField)
{
	int	i;

	m_bf1IsPlayOnGuildBattle	=	TRUE;	//	길드전 중이다
	m_iHP						=	getMaxHP();
	m_iCP						=	getMaxCP();

	sendEtcWork(eEW_OPERATE_DUEL_MATCH,3);

	g_pMoveFieldUserManager->booking(this,NULL,_iDuelField,0);

	cItem	aBuffItem[4];

	for (i=0;i<4;i++)
	{
		g_im.generateItemByBaseItem(&aBuffItem[i],g_im.m_awDuelBuffItem[i],c_iBuffForDuelItemCount);
		aBuffItem[i].m_dwSerial	=	largeRandom(0x7fffffff)+10;
	}

	for (i=dEQUIP_BELT_SLOT1;i<=dEQUIP_BELT_SLOT5;i++)
	{
		cItem	*lpItem	=	&m_aEquip[i];

		if	(lpItem->m_wBaseItem	==	0xffff)
			continue;

		if	(lpItem->checkFirstEffect(eIE_DUEL_BUFF_FIRE)	||
			lpItem->checkFirstEffect(eIE_DUEL_BUFF_WATER)	||
			lpItem->checkFirstEffect(eIE_DUEL_BUFF_WIND)	||
			lpItem->checkFirstEffect(eIE_DUEL_BUFF_EARTH))
			lpItem->reset();
	}

	for (i=0;i<dOWN_ITEM_COUNT;i++)
	{
		cItem	*lpItem	=	&m_aItems[i];

		if	(lpItem->m_wBaseItem	==	0xffff)
			continue;

		if	(lpItem->checkFirstEffect(eIE_DUEL_BUFF_FIRE)	||
			lpItem->checkFirstEffect(eIE_DUEL_BUFF_WATER)	||
			lpItem->checkFirstEffect(eIE_DUEL_BUFF_WIND)	||
			lpItem->checkFirstEffect(eIE_DUEL_BUFF_EARTH))
			lpItem->reset();
	}

	for (i=0;i<m_bf6ExtraInventorySize;i++)
	{
		cItem	*lpItem	=	&m_aExtraInventory[i];

		if	(lpItem->m_wBaseItem	==	0xffff)
			continue;

		if	(lpItem->checkFirstEffect(eIE_DUEL_BUFF_FIRE)	||
			lpItem->checkFirstEffect(eIE_DUEL_BUFF_WATER)	||
			lpItem->checkFirstEffect(eIE_DUEL_BUFF_WIND)	||
			lpItem->checkFirstEffect(eIE_DUEL_BUFF_EARTH))
			lpItem->reset();
	}

	for (i=0;i<c_iDuelBuffCount;i++)
		m_aEquip[dEQUIP_BELT_SLOT1+i].copy(&aBuffItem[i]);
}

void
cACTOR::closeTrade()
{
	if	(m_wTradeBoxSerial	==	0xffff)
		return;

	if	(isPlayer()	==	FALSE || !m_lpField)
		return;

	CTradeBox	*lpTradeBox	=	m_lpField->m_tradeManager.getTradeBox(this);

	if	(!lpTradeBox)
		return;

	cACTOR		*lpMate		=	lpTradeBox->getTradeMate(this);

	if	(lpMate	&&	lpMate->isCorrectClient())
	{
		SG_TRADE_MESSAGE	packet;

		packet.base.set(sizeof(packet),dSG_TRADE_MESSAGE);

		packet.wMessage	=	eTM_TRADE_CANCEL_BY_TRADE_MATE;
		g_userPM.add(lpMate->m_iClientSerial,&packet,packet.base.wSize);	//	트레이드 중이 아니여..

		lpMate->m_wTradeBoxSerial	=	0xffff;
	}

	m_lpField->m_tradeManager.removeTradeBox(m_wTradeBoxSerial,m_strName);
}

BOOL
cACTOR::isUnionPartyMember()
{
	cParty*		lpParty		=	getParty();

	if(!lpParty)
		return FALSE;

	if(lpParty->m_wUnionPartyserial == 0xffff)
		return FALSE;

	return TRUE;
}

LONGLONG
cACTOR::getOwnGoldSum()
{
	LONGLONG	llOwnGold	= getItemCount(dITEM_INDEX_GOLD_BAR, FALSE);

	llOwnGold	*=	100000000;

	llOwnGold	+=	m_iGold;
	
	return	llOwnGold;
}
